CREATE TABLE `facturas` (
  `id_factura` bigint(20) UNSIGNED NOT NULL,
  `id_paciente_seguro` bigint(20) UNSIGNED NOT NULL,
  `id_usuario_factura` bigint(20) UNSIGNED NOT NULL,
  `id_datos_facturacion` bigint(20) UNSIGNED NOT NULL,
  `tipo_pago` enum('PARTICULAR','SEGURO','MIXTO') NOT NULL,
  `subtotal` decimal(12,2) NOT NULL DEFAULT 0.00,
  `monto_cobertura_seguro` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total` decimal(12,2) GENERATED ALWAYS AS (`subtotal` - `monto_cobertura_seguro`) STORED,
