--
-- Estructura de tabla para la tabla `factura_detalle`
--

CREATE TABLE `factura_detalle` (
  `id_detalle` bigint(20) UNSIGNED NOT NULL,
  `id_factura` bigint(20) UNSIGNED NOT NULL,
  `id_servicio` bigint(20) UNSIGNED NOT NULL,
  `id_consulta` bigint(20) UNSIGNED DEFAULT NULL,
  `id_cirugia` bigint(20) UNSIGNED DEFAULT NULL,
  `id_internacion` bigint(20) UNSIGNED DEFAULT NULL,
  `cantidad` decimal(10,2) NOT NULL DEFAULT 1.00,
  `precio_unitario` decimal(12,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(12,2) GENERATED ALWAYS AS (`cantidad` * `precio_unitario`) STORED
) ;

--
-- Disparadores `factura_detalle`
--
DELIMITER $$
CREATE TRIGGER `trg_factura_detalle_recalcula_subtotal` AFTER INSERT ON `factura_detalle` FOR EACH ROW BEGIN
    UPDATE facturas f
    SET f.subtotal = (SELECT COALESCE(SUM(fd.subtotal),0) FROM factura_detalle fd WHERE fd.id_factura = NEW.id_factura)
    WHERE f.id_factura = NEW.id_factura;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_factura_detalle_recalcula_subtotal_delete` AFTER DELETE ON `factura_detalle` FOR EACH ROW BEGIN
    UPDATE facturas f
    SET f.subtotal = (SELECT COALESCE(SUM(fd.subtotal),0) FROM factura_detalle fd WHERE fd.id_factura = OLD.id_factura)
    WHERE f.id_factura = OLD.id_factura;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_factura_detalle_recalcula_subtotal_update` AFTER UPDATE ON `factura_detalle` FOR EACH ROW BEGIN
    UPDATE facturas f
    SET f.subtotal = (SELECT COALESCE(SUM(fd.subtotal),0) FROM factura_detalle fd WHERE fd.id_factura = NEW.id_factura)
    WHERE f.id_factura = NEW.id_factura;
END
$$
DELIMITER ;

