-- Estructura de tabla para la tabla `internaciones`
--

CREATE TABLE `internaciones` (
  `id_internacion` bigint(20) UNSIGNED NOT NULL,
  `id_orden` bigint(20) UNSIGNED NOT NULL,
  `id_persona` bigint(20) UNSIGNED NOT NULL,
  `id_habitacion` bigint(20) UNSIGNED NOT NULL,
  `fecha_ingreso` datetime NOT NULL,
  `fecha_alta` datetime DEFAULT NULL,
  `id_medico_autoriza_alta` bigint(20) UNSIGNED DEFAULT NULL,
  `estado` enum('ACTIVA','FINALIZADA','CANCELADA') NOT NULL DEFAULT 'ACTIVA'
) ;

--
-- Disparadores `internaciones`
--
DELIMITER $$
CREATE TRIGGER `trg_internacion_alta_valida` BEFORE UPDATE ON `internaciones` FOR EACH ROW BEGIN
    IF NEW.estado = 'FINALIZADA' AND NEW.fecha_alta IS NULL THEN
        SET NEW.fecha_alta = CURRENT_TIMESTAMP;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_internacion_habitacion_ocupada` BEFORE INSERT ON `internaciones` FOR EACH ROW BEGIN
    IF EXISTS (SELECT 1 FROM internaciones WHERE id_habitacion = NEW.id_habitacion AND estado = 'ACTIVA') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La habitación seleccionada ya está ocupada';
    END IF;
END
$$
DELIMITER ;

